<?php
use XcVm\Core\Auth\Authorization;
use XcVm\Core\Proxy\ProxyProfiles;
use XcVm\Core\Util\LayoutRenderer;
$ar=($rUserInfo['lang']??'')==='ar';$t=static fn($en,$arabic)=>$ar?$arabic:$en;$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$profiles=ProxyProfiles::app();
$states=['unconfigured'=>$t('Needs configuration','يحتاج ضبط'),'not_connected'=>$t('Waiting for installation','في انتظار التثبيت'),'offline'=>$t('Agent offline','الوكيل غير متصل'),'failed'=>$t('Apply failed','تعذر التطبيق'),'pending'=>$t('Pending application','في انتظار التطبيق'),'applied'=>$t('Applied & confirmed','مطبّق ومؤكد')];
?>
<link rel="stylesheet" href="./assets/horus/proxy.css?v=<?= filemtime(MAIN_HOME.'Public/assets/admin/horus/proxy.css') ?>">
<section class="hp" dir="<?= $ar?'rtl':'ltr' ?>"><header class="hp-hero"><div><span class="hp-eyebrow">HORUS · EDGE NETWORK</span><h1><?= $t('Proxy servers','سيرفرات البروكسي') ?></h1><p><?= $t('Manage routes, ports and confirmed deployments.','إدارة التوجيه والبورتات ومتابعة تطبيق الإعدادات.') ?></p></div><?php if(Authorization::check('adv','add_server')): ?><a class="btn btn-light" href="./proxy?new=1">+ <?= $t('Add proxy','إضافة بروكسي') ?></a><?php endif ?></header>
<div class="row g-3"><?php $count=0;foreach($rServers as $server):if((int)$server['server_type']!==1)continue;$count++;$id=(int)$server['id'];$s=$profiles->status($id);$doc=$profiles->document($id);$p=$doc['profile']??null; ?>
 <div class="col-12 col-xl-6"><article class="hp-card h-100"><div class="d-flex justify-content-between align-items-start gap-2 mb-3"><div><h2><?= $e($server['server_name']) ?></h2><code><?= $e($server['server_ip']) ?></code></div><span class="hp-pill" data-state="<?= $e($s['state']) ?>"><?= $e($states[$s['state']]) ?></span></div><p><?= $t('Applied traffic setting','حالة المرور المطبقة') ?>: <strong><?= $server['enabled']?$t('Enabled','مفعّل'):$t('Disabled','معطّل') ?></strong></p>
 <?php if($p): ?><p class="hp-note"><?= $t('Saved configuration','الإعدادات المحفوظة') ?></p><div class="hp-fields"><div>HTTP <code><?= $e(implode(', ',$p['http_ports']))?:'—' ?></code><br>HTTPS <code><?= $e(implode(', ',$p['https_ports']))?:'—' ?></code></div><div><?= count($p['hosts']) ?> <?= $t('hosts','هوستات') ?><br><?= count($p['parent_ids']) ?> <?= $t('upstreams','سيرفرات خلفية') ?></div></div><?php endif ?>
 <?php $metrics=json_decode((string)($server['watchdog_data']??''),true)?:[];$live=\XcVm\Domain\Stream\ConnectionTracker::getLiveConnections($id,true);$fresh=$s['last_sync']&&time()-$s['last_sync']<=30; ?>
 <div class="row g-2 small mb-3"><div class="col-4">CPU<br><strong><?= $fresh?number_format(max(0,min(100,(float)($metrics['cpu']??0))),1).'%':'—' ?></strong></div><div class="col-4">RAM<br><strong><?= $fresh?number_format(max(0,min(100,(float)($metrics['total_mem_used_percent']??0))),1).'%':'—' ?></strong></div><div class="col-4"><?= $t('Connections','الاتصالات') ?><br><strong><?= $live===false?'—':(int)$live ?> / <?= (int)($server['total_clients']??0) ?></strong></div><div class="col-12"><?= $t('Network out / in','الشبكة إرسال / استقبال') ?>: <strong dir="ltr"><?= $fresh?number_format((float)($metrics['bytes_sent']??0)*8/1000000,2).' / '.number_format((float)($metrics['bytes_received']??0)*8/1000000,2).' Mbps':'—' ?></strong></div></div>
 <?php if($s['last_error']): ?><p class="text-danger small" style="overflow-wrap:anywhere"><?= $e($s['last_error']) ?></p><?php endif ?>
 <?php if(Authorization::check('adv','edit_server')): ?><div class="d-flex flex-wrap gap-2"><a class="btn btn-primary btn-sm" href="./proxy?id=<?= $id ?>"><?= $t('Configure','الإعدادات') ?></a><?php foreach(['enable'=>$t('Enable','تفعيل'),'disable'=>$t('Disable','تعطيل'),'kill'=>$t('Close connections','إغلاق الاتصالات'),'delete'=>$t('Delete','حذف')] as $action=>$label): ?><button class="btn btn-sm btn-outline-secondary" type="button" data-proxy-action="<?= $action ?>" data-id="<?= $id ?>"><?= $e($label) ?></button><?php endforeach ?><?php if(Authorization::isFullAdmin()): ?><button class="btn btn-sm btn-outline-warning" data-proxy-action="rotate_key" data-id="<?= $id ?>"><?= $t('Revoke installer key','إلغاء مفتاح التثبيت') ?></button><?php endif ?></div><?php endif ?>
 </article></div>
<?php endforeach;if(!$count): ?><div class="col-12"><div class="hp-card text-center py-5"><h2><?= $t('Your edge network starts here','ابدأ شبكة البروكسي من هنا') ?></h2><p class="mt-3"><?= $t('Register a proxy, save its settings, then install its private package on a separate server.','أضف بروكسي واحفظ إعداداته، ثم ثبّت الحزمة الخاصة به على سيرفر منفصل.') ?></p></div></div><?php endif ?></div></section>
<?php LayoutRenderer::renderFooter('admin'); ?>
<script>
document.addEventListener('click',async event=>{const button=event.target.closest('[data-proxy-action]');if(!button)return;const action=button.dataset.proxyAction;if(!confirm(<?= json_encode($t('Apply this action? Disable / delete / revoke can interrupt viewer connections.','تنفيذ الإجراء؟ التعطيل أو الحذف أو إلغاء المفتاح قد يقطع اتصالات المشاهدين.')) ?>))return;button.disabled=true;try{const response=await fetch('./api?action=proxy_profile&sub='+action+'&id='+button.dataset.id,{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:new URLSearchParams({csrf:<?= json_encode($_SESSION['horus_proxy_csrf']) ?>})});const answer=await response.json();if(!answer.result)throw Error(answer.error||'FAILED');location.reload();}catch(error){alert(error.message);button.disabled=false;}});
</script></body></html>
